  const latest = sortForumThreads(rest, "latest").slice(0, HOME_LATEST_LIMIT);
  if (pinned.length > 0) {
    page.append(renderSectionHead("\u516C\u544A\u4E0E\u7F6E\u9876", `${pinned.length} \u6761`), renderThreadList(context, pinned));
  }
  if (hot.length > 0) {
    page.append(renderSectionHead("\u6B63\u5728\u53D1\u9175", "\u9996\u9875\u53EA\u4FDD\u7559 3 \u4E2A\u7126\u70B9"), renderThreadList(context, hot));
  }
  page.append(renderSectionHead("\u521A\u521A\u53D1\u751F", `\u6700\u8FD1 ${latest.length} \u4E2A\u4E3B\u9898`), renderThreadList(context, latest));
  page.append(renderHomeShortcuts(context));
