  page.append(renderSectionHead("\u70ED\u5EA6\u6392\u540D", `TOP ${Math.min(HOT_RANK_LIMIT, index.threads.length)}`), ranking);
  const activity = collectForumActivity(index).slice(0, 10);
  page.append(renderSectionHead("\u5B9E\u65F6\u8BA8\u8BBA\u6D41", activity.length > 0 ? `${activity.length} \u6761\u6700\u8FD1\u56DE\u590D` : "\u6682\u65E0\u697C\u5C42\u6D3B\u52A8"));
  if (activity.length > 0) page.append(renderActivityStream(context, activity));
