  const joined = sortForumThreads(index.threads.filter((view) => view.thread.profileId !== selfId && view.floors.some((floor) => containsSelfFloor(floor, selfId))), "latest");
  const page = element("div", { className: "phone-page phone-forum-page phone-forum-me-page" });
  page.append(renderForumHeader("\u6211\u7684\u8BBA\u575B", "\u516C\u5F00\u8EAB\u4EFD\u3001\u8BBA\u575B\u53C2\u6570\u4E0E\u4E2A\u4EBA\u8BA8\u8BBA\u8BB0\u5F55\u96C6\u4E2D\u7BA1\u7406"));
