    shortcut("\u67E5\u770B\u70ED\u699C", "\u6392\u540D\u4E0E\u5B9E\u65F6\u56DE\u590D\u6D41", "summary", () => context.navigate("forumHot")),
    shortcut("\u8BBA\u575B\u7BA1\u7406", "\u8EAB\u4EFD\u3001\u53C2\u6570\u4E0E\u6211\u7684\u5185\u5BB9", "settings", () => context.navigate("forumMe"))
