function renderTestCard(context) {
  const card = element("section", { className: "phone-vector-card" });
  card.append(element("strong", { text: "\u68C0\u7D22\u6D4B\u8BD5" }));
  const form = element("form", { className: "phone-vector-test-form" });
  const input = element("input", {
    className: "phone-input",
    attributes: { type: "text", placeholder: "\u8F93\u5165\u4E0B\u4E00\u6BB5\u5267\u60C5\u7684\u5173\u952E\u8BCD\u8BD5\u8BD5\u2026", maxlength: "200" }
  });
  const submit = button("\u68C0\u7D22", "phone-button phone-button-primary phone-button-compact");
  form.append(input, submit);
  const results = element("div", { className: "phone-vector-results" });
  const run = async () => {
    const query = input.value.trim();
    if (!query) return;
    submit.disabled = true;
    submit.textContent = "\u68C0\u7D22\u4E2D\u2026";
    results.replaceChildren();
    try {
      const hits = await context.vector.test(query);
      if (hits.length === 0) {
        results.append(element("p", { className: "phone-vector-status", text: "\u6CA1\u6709\u68C0\u7D22\u5230\u76F8\u5173\u8BB0\u5FC6\u3002" }));
      }
      for (const hit of hits) {
        const row = element("article", { className: "phone-vector-hit" });
        const head = element("div", { className: "phone-vector-hit-head" });
        head.append(
          element("span", { className: "phone-memory-item-seq", text: `\u8BB0\u5FC6#${hit.seq}` }),
          element("span", { className: "phone-memory-item-kind", text: hit.kind === "summary" ? "\u6458\u8981" : "\u603B\u7ED3" }),
          element("small", { text: `\u76F8\u5173\u5EA6 ${hit.score.toFixed(3)}` })
        );
        row.append(head, element("p", { className: "phone-vector-hit-text", text: hit.content.slice(0, 200) }));
        results.append(row);
      }
    } catch (error) {
      const message2 = error instanceof Error ? error.message : String(error);
      results.append(element("p", {
        className: "phone-vector-status",
        text: message2
      }));
      context.showNotice(`\u5411\u91CF\u68C0\u7D22\u5931\u8D25\uFF1A${message2}`, "error");
    } finally {
      submit.disabled = false;
      submit.textContent = "\u68C0\u7D22";
    }
  };
  form.addEventListener("submit", (event) => {
    event.preventDefault();
    void run();
  });
  submit.addEventListener("click", () => void run());
  card.append(form, results);
  return card;
}

