// src/conditions/context-source.ts
function createConditionSource(deps) {
  let variables = {};
  const compile = () => {
    const base = createConditionContext({
      state: deps.state(),
      variables,
      worldBook: deps.worldBook(),
      appAccess: deps.appAccess()
    });
    return buildRuleConditionContext(base.snapshot, deps.rules());
  };
  return {
    context: compile,
    refresh: async () => {
      try {
        const snapshot = await readVariables("message", null);
        if (snapshot.available) variables = snapshot.data;
      } catch {
      }
      return compile();
    }
  };
}

// src/core/event-bus.ts
var CleanupStack = class {
  #cleanups = [];
  #disposed = false;
  add(cleanup) {
    if (!cleanup) return;
    if (this.#disposed) {
      cleanup();
      return;
    }
    this.#cleanups.push(cleanup);
  }
  dispose() {
    if (this.#disposed) return;
    this.#disposed = true;
    for (const cleanup of this.#cleanups.splice(0).reverse()) {
      try {
        cleanup();
      } catch (error) {
        console.warn("[\u58A8\u97F5\u624B\u673A] \u6E05\u7406\u8D44\u6E90\u5931\u8D25", error);
      }
    }
  }
};

