function formatDateKey(timestamp) {
  const date = new Date(timestamp);
  const pad = (value) => String(value).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}
function appearanceRoster(state) {
  return Object.values(state.profiles).filter((profile) => (profile.appearancePrompt ?? "").trim().length > 0).map((profile) => {
    const preview = (profile.appearancePrompt ?? "").trim().slice(0, 60);
    return `@${profile.displayName}\uFF08${preview}\uFF09`;
  });
}
