function renderForceCompatReport(result) {
  const wrap2 = element("div", { className: "phone-force-compat-result" });
  wrap2.append(element("strong", { className: result.ok ? "is-ok" : "is-failed", text: result.message }));
  if (result.accepted.length > 0) {
    const list3 = element("ul", { className: "phone-force-compat-list" });
    for (const item of result.accepted) list3.append(element("li", { text: `\u5DF2\u542F\u7528\uFF1A${item}` }));
    wrap2.append(list3);
  }
  if (result.rejected.length > 0) {
    const list3 = element("ul", { className: "phone-force-compat-list is-rejected" });
    for (const item of result.rejected.slice(0, 8)) list3.append(element("li", { text: `\u5DF2\u4E22\u5F03\uFF1A${item}` }));
    wrap2.append(list3);
  }
  return wrap2;
}
function withoutAdapterOverride(overrides, adapterId) {
  const next = { ...overrides };
  delete next[adapterId];
  return next;
}
