function renderPromptPresetSection(context, config, patch) {
  const box = element("div", { className: "phone-setting-control phone-setting-control-stack" });
  box.append(element("span", { className: "phone-control-label", text: "\u63D0\u793A\u8BCD\u9884\u8BBE" }));
  const row = element("div", { className: "phone-inline-group" });
  const select = element("select", { className: "phone-select phone-preset-select" });
  select.append(element("option", { text: config.promptPresets.length > 0 ? "\u2014 \u9009\u62E9\u9884\u8BBE\u4EE5\u5E94\u7528 \u2014" : "\uFF08\u8FD8\u6CA1\u6709\u4FDD\u5B58\u7684\u9884\u8BBE\uFF09", attributes: { value: "" } }));
  for (const preset of config.promptPresets) {
    select.append(element("option", { text: preset.name, attributes: { value: preset.name } }));
  }
  select.addEventListener("change", () => {
    const preset = config.promptPresets.find((item) => item.name === select.value);
    if (!preset) return;
    void Promise.resolve().then(() => patch({ positivePrompt: preset.positive, negativePrompt: preset.negative })).then(() => context.showNotice(`\u5DF2\u5E94\u7528\u9884\u8BBE\u300C${preset.name}\u300D\u3002`, "success")).catch((error) => context.showNotice(error instanceof Error ? error.message : String(error), "error"));
  });
  const save = button("\u4FDD\u5B58\u5F53\u524D", "phone-button phone-button-secondary phone-button-compact", async () => {
    const host = document.getElementById("narrative-phone-host");
    const shell = host?.shadowRoot?.querySelector(".phone-shell");
    if (!shell) return;
    const values = await showModal(shell, "\u4FDD\u5B58\u63D0\u793A\u8BCD\u9884\u8BBE", [
      { name: "name", label: "\u9884\u8BBE\u540D\u79F0", required: true, placeholder: "\u4F8B\u5982\uFF1A\u65E5\u5E38\u63D2\u753B\u98CE" }
    ]);
    const name = values?.name?.trim().slice(0, 40);
    if (!name) return;
    const others = config.promptPresets.filter((item) => item.name !== name);
    await patch({
      promptPresets: [...others, { name, positive: config.positivePrompt, negative: config.negativePrompt }]
    });
    context.showNotice(`\u9884\u8BBE\u300C${name}\u300D\u5DF2\u4FDD\u5B58\u3002`, "success");
  });
  const remove = button("\u5220\u9664\u6240\u9009", "phone-button phone-button-danger phone-button-compact", async () => {
    const name = select.value;
    if (!name) {
      context.showNotice("\u8BF7\u5148\u5728\u4E0B\u62C9\u6846\u4E2D\u9009\u62E9\u8981\u5220\u9664\u7684\u9884\u8BBE\u3002", "info");
      return;
    }
    await patch({ promptPresets: config.promptPresets.filter((item) => item.name !== name) });
    context.showNotice(`\u9884\u8BBE\u300C${name}\u300D\u5DF2\u5220\u9664\u3002`, "info");
  });
  row.append(select, save, remove);
  box.append(row, element("small", {
    className: "phone-settings-hint",
    text: "\u300C\u4FDD\u5B58\u5F53\u524D\u300D\u4F1A\u628A\u4E0A\u9762\u7684\u56FA\u5B9A\u6B63/\u8D1F\u9762\u63D0\u793A\u8BCD\u5B58\u6210\u4E00\u4E2A\u9884\u8BBE\uFF1B\u9009\u62E9\u9884\u8BBE\u5373\u53EF\u4E00\u952E\u5207\u6362\u3002"
  }));
  return box;
}
