// src/ui/notice-lifecycle.ts
var DEFAULT_NOTICE_DURATION_MS = 5e3;
function normalizeNoticeDuration(durationMs, fallback = DEFAULT_NOTICE_DURATION_MS) {
  const safeFallback = Number.isFinite(fallback) && fallback > 0 ? fallback : DEFAULT_NOTICE_DURATION_MS;
  return typeof durationMs === "number" && Number.isFinite(durationMs) && durationMs > 0 ? durationMs : safeFallback;
}
function showAutoDismissNotice(element2, timer, message2, kind, durationMs) {
  element2.textContent = message2;
  element2.dataset.kind = kind;
  element2.classList.add("is-visible");
  timer.schedule(() => element2.classList.remove("is-visible"), durationMs);
}
function hideAutoDismissNotice(element2, timer) {
  timer.clear();
  element2.classList.remove("is-visible");
}
function createNoticeTimer(host, fallbackDurationMs = DEFAULT_NOTICE_DURATION_MS) {
  let handle = null;
  const clear2 = () => {
    if (handle === null) return;
    host.clearTimeout(handle);
    handle = null;
  };
  const schedule = (callback, durationMs) => {
    clear2();
    handle = host.setTimeout(() => {
      handle = null;
      callback();
    }, normalizeNoticeDuration(durationMs, fallbackDurationMs));
  };
  return { clear: clear2, schedule };
}

