    const floor = getLatestFloorIndex();
    const context = getSillyTavernContext();
    const message2 = Array.isArray(context.chat) ? context.chat[floor] : void 0;
    if (!message2 || message2.is_user === true || message2.is_system === true) return;
    const existing = this.#phoneMemoryAttachments.findIndex((item) => item.batchId === pending2.batchId);
    const attachment = { batchId: pending2.batchId, targetFloor: floor, text: pending2.text };
    if (existing >= 0) this.#phoneMemoryAttachments.splice(existing, 1, attachment);
