    if (!report2 || !isCurrent()) return;
    phoneLogger.info("\u6570\u636E\u4E2D\u5FC3\u5DF2\u56DE\u64A4\u53D8\u66F4\u697C\u5C42\u7684\u5199\u5165", {
      scopeId,
      floor,
      reason,
      entries: report2.entries,
      tables: report2.tables,
      projections: report2.projections.length
    });
    if (this.#store.scopeId !== scopeId || getCurrentScopeId() !== scopeId) return;
