        system: prompt.system,
        user: prompt.user,
        temperature: organizeApi.temperature ?? 0.3,
        maxTokens: organizeApi.maxTokens ?? Math.max(600, Math.round(targetLength * 2.5)),
        signal: this.#summaryRun.begin(),
