      const message2 = `\u5DF2\u603B\u7ED3 ${digest.count} \u6761\u624B\u673A\u5185\u5BB9\uFF08\u624B\u673A#${item.seq}\uFF0C${item.content.length} \u5B57\uFF09\uFF0C\u65E7\u5185\u5BB9\u6B64\u540E\u53EA\u6CE8\u5165\u603B\u7ED3\u3002`;
